"""n takes priority
    """
def get_number_and_percentage(total: Any, n: Any, percentage: Any) -> object {
    if (n == -1) {
        return (total, 1.0);
    } elif ((n is not None) and (n > 0)) {
        if (n >= total) {
            return (total, 1.0);
        } else {
            return (n, (float(n) / total));
        }
    } else {
        assert isinstance(percentage, float);
        return (int((total * percentage)), percentage);
    }
}

