"""
    Given a window and a set of disjoint subintervals, return the
    "holes", which are the intervals of the refWindow not covered by
    the given subintervals.
    """
def holes(refWindow: Any, intervals: Any) -> object {
    (winId, winStart, winEnd) = refWindow;
    output = [];
    intervals = sorted(intervals);
    lastE = winStart;
    for (s, e) in intervals {
        if (s > lastE) {
            output.append((lastE, s));
        }
        lastE = e;
    }
    if (lastE < winEnd) {
        output.append((lastE, winEnd));
    }
    return output;
}

"""Prints if the binary was found in the given path.

    :param binary: The full path to the binary that needs to be verified.

    :return True: If the binary was found
        False: If the binary was not found.
    """
def is_valid_binary(binary: Any) -> object {
    import os;
    return (os.path.isfile(binary) and os.access(binary, os.X_OK));
}

